SELECT 'gongkao', '已知现年龄求关系', 'kp-age-b-now-relation', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "已知现年龄求关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "一切基于当下的已知数字，顺向推导，最基础的心算题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲今年 30岁，乙今年 12岁。问……” 题目明牌给出所有人的当前年龄，让你找几年后的关系。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{X年后甲的年龄} = \\text{甲现龄} + X \\quad ; \\quad \\text{X年前甲的年龄} = \\text{甲现龄} - X"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出所有人今年的具体年龄] --> B{题目要求什么关系?}\nB -- 求几年后倍数 --> C[设 X 年后, 所有人年龄加上 X]\nB -- 求几年前倍数 --> D[设 X 年前, 所有人年龄减去 X]\nC --> E[根据要求的倍数关系列一元一次方程]\nD --> E\nE --> F[因为选项通常是整数, 首推带入选项直接验算!]"}}]}$$ AS jsonb), NULL, '已知现年龄求关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "已知现年龄求关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_b_now_relation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
